import React from 'react'
import { HeadFC, PageProps, Script } from 'gatsby'
import ReolMapLayout from '../../components/reolmap/layout/ReolMapLayout'

const ReolMapPage: React.FC<PageProps> = () => {
  return <ReolMapLayout />
}

export const Head: HeadFC = () => {
  // クライアントサイドで言語を判定（ビルド時はデフォルト日本語）
  const getMetaContent = () => {
    if (typeof window === 'undefined') {
      // サーバーサイド/ビルド時はデフォルト（日本語）
      return {
        title: '美辞学ナビ - 会場・アクセス・参加者情報',
        description: '美辞学ツアーの会場情報や参加者をチェックできます'
      }
    }
    
    // クライアントサイドで言語を取得
    const language = localStorage.getItem('reol-language') || 'ja'
    
    if (language === 'en') {
      return {
        title: 'Bijigaku Navi - Venue, Access & Attendee Information',
        description: 'Check venue information and attendees for the Bijigaku tour'
      }
    }
    
    return {
      title: '美辞学ナビ - 会場・アクセス・参加者情報',
      description: '美辞学ツアーの会場情報や参加者をチェックできます'
    }
  }

  const meta = getMetaContent()

  return (
    <>
      <title>{meta.title}</title>
      <meta name="description" content={meta.description} />
      <meta property="og:title" content={meta.title} />
      <meta property="og:description" content={meta.description} />
      <meta property="og:type" content="website" />
      <meta name="twitter:card" content="summary" />
    </>
  )
}

export default ReolMapPage